export fn largest_divisible_subset(v:[*]const i64,n:usize)i64{if(n>64)return -1;var a:[64]i64=@splat(0);var d:[64]i64=@splat(1);for(0..n)|i|{if(v[i]<1 or v[i]>50000)return -1;a[i]=v[i];}for(1..n)|i|{const x=a[i];var j=i;while(j>0 and a[j-1]>x){a[j]=a[j-1];j-=1;}a[j]=x;}var best:i64=0;for(0..n)|i|{d[i]=1;for(0..i)|j|{if(@rem(a[i],a[j])==0 and d[j]+1>d[i])d[i]=d[j]+1;}if(d[i]>best)best=d[i];}return best;}
